const fs = require('fs');
const path = require('path');
const root = '.ticket/tickets';
const rows = [];
for (const entry of fs.readdirSync(root, { withFileTypes: true })) {
  if (entry.isDirectory() === false) continue;
  const ticketPath = path.join(root, entry.name, 'ticket.toml');
  const historyPath = path.join(root, entry.name, 'history.ndjson');
  if (fs.existsSync(ticketPath) === false || fs.existsSync(historyPath) === false) continue;
  const title = (fs.readFileSync(ticketPath, 'utf8').match(/^title\s*=\s*"(.*)"$/m) || [])[1] || '(untitled)';
  for (const line of fs.readFileSync(historyPath, 'utf8').split(/\r?\n/).filter(Boolean)) {
    try {
      const text = JSON.stringify(JSON.parse(line));
      if (text.includes('github-copilot') && text.includes('done') && text.includes('2026-08-10T19:')) rows.push([entry.name.slice(0, 8), title]);
    } catch {}
  }
}
rows.sort((left, right) => left[0].localeCompare(right[0]));
console.log(rows.map(([id, title]) => `- ${id} ${title}`).join('\n'));
console.error(`COUNT=${rows.length}`);
